        CHECK(look.find("Reveal: you looked at the top") != string::npos
              && look.find("Search:") == string::npos,
              "W35-N166p NEGATIVE a real top-of-library look is byte-unchanged");
        // NEGATIVE: a HAND reveal is neither.
